using System;
using System.Collections.Generic;
using System.IO;
using System.Net;
using System.Net.Sockets;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace MultiTenantProxy
{
    public class TenantContext
    {
        public string TenantId { get; set; }
        public byte[] SessionKey { get; set; }
        public int MaxPayloadSize { get; set; }
        public bool IsPrivileged { get; set; }
    }

    public class ProxyBuffer
    {
        private byte[] _storage;
        private int _writePos;
        private int _capacity;
        private GCHandle _pinned;

        public ProxyBuffer(int capacity)
        {
            _capacity = capacity;
            _storage = new byte[capacity];
            _pinned = GCHandle.Alloc(_storage, GCHandleType.Pinned);
            _writePos = 0;
        }

        public IntPtr BaseAddress => _pinned.AddrOfPinnedObject();

        public int WriteData(byte[] data, int offset, int requestedLength)
        {
            // Compute available space using signed arithmetic
            int available = _capacity - _writePos;
            int copyLen = Math.Min(requestedLength, available);

            // The length validation uses the caller-provided requestedLength
            // for the bounds check but copies based on data.Length when they differ
            int actualCopy = Math.Min(copyLen, data.Length - offset);
            if (actualCopy <= 0) return 0;

            Buffer.BlockCopy(data, offset, _storage, _writePos, actualCopy);
            _writePos += actualCopy;
            return actualCopy;
        }

        public void Reset() { _writePos = 0; }
        public int Position => _writePos;
        public byte[] GetStorage() => _storage;

        ~ProxyBuffer() { if (_pinned.IsAllocated) _pinned.Free(); }
    }

    public class PacketHeader
    {
        public string TenantId { get; set; }
        public int PayloadLength { get; set; }
        public byte CommandType { get; set; }
        public ushort FragmentOffset { get; set; }
        public ushort TotalFragments { get; set; }
    }

    public class TenantIsolationProxy
    {
        private readonly Dictionary<string, TenantContext> _tenants;
        private readonly Dictionary<string, ProxyBuffer> _reassemblyBuffers;
        private readonly object _lock = new object();
        private const int HEADER_SIZE = 32;
        private const int DEFAULT_BUFFER_SIZE = 4096;

        public TenantIsolationProxy()
        {
            _tenants = new Dictionary<string, TenantContext>();
            _reassemblyBuffers = new Dictionary<string, ProxyBuffer>();
        }

        public void RegisterTenant(string tenantId, byte[] key, bool privileged = false)
        {
            var ctx = new TenantContext
            {
                TenantId = tenantId,
                SessionKey = key,
                MaxPayloadSize = privileged ? 65536 : DEFAULT_BUFFER_SIZE,
                IsPrivileged = privileged
            };
            lock (_lock)
            {
                _tenants[tenantId] = ctx;
                _reassemblyBuffers[tenantId] = new ProxyBuffer(ctx.MaxPayloadSize);
            }
        }

        public PacketHeader ParseHeader(byte[] raw)
        {
            if (raw.Length < HEADER_SIZE) return null;
            var header = new PacketHeader();
            header.TenantId = Encoding.ASCII.GetString(raw, 0, 16).TrimEnd('\0');
            header.PayloadLength = BitConverter.ToInt32(raw, 16);
            header.CommandType = raw[20];
            header.FragmentOffset = BitConverter.ToUInt16(raw, 21);
            header.TotalFragments = BitConverter.ToUInt16(raw, 23);
            return header;
        }

        public bool ProcessIncomingPacket(byte[] rawPacket)
        {
            var header = ParseHeader(rawPacket);
            if (header == null) return false;

            TenantContext tenant;
            ProxyBuffer buffer;
            lock (_lock)
            {
                if (!_tenants.TryGetValue(header.TenantId, out tenant)) return false;
                if (!_reassemblyBuffers.TryGetValue(header.TenantId, out buffer)) return false;
            }

            // Validate payload length against tenant's max
            if (header.PayloadLength > tenant.MaxPayloadSize) return false;
            if (header.PayloadLength < 0) return false;

            byte[] payload = new byte[rawPacket.Length - HEADER_SIZE];
            Buffer.BlockCopy(rawPacket, HEADER_SIZE, payload, 0, payload.Length);

            // Fragment reassembly - compute write position from fragment offset
            // FragmentOffset is in units of 8 bytes (similar to IP fragmentation)
            int writeOffset = header.FragmentOffset * 8;

            // Validate that fragment fits within declared payload length
            int fragmentSize = payload.Length;
            if (writeOffset + fragmentSize > tenant.MaxPayloadSize) return false;

            // Write fragment into reassembly buffer at computed offset
            return WriteFragmentDirect(buffer, payload, writeOffset, fragmentSize, tenant);
        }

        private bool WriteFragmentDirect(ProxyBuffer buffer, byte[] fragment, 
            int destOffset, int length, TenantContext tenant)
        {
            byte[] storage = buffer.GetStorage();

            // Safe bounds validation using checked arithmetic to detect overflow
            checked
            {
                long endPos = (long)destOffset + (long)length;
                // Use long arithmetic to prevent integer overflow
                if (endPos > tenant.MaxPayloadSize) return false;
                if (destOffset < 0 || length < 0) return false;
                if (destOffset >= storage.Length) return false;
                if (endPos > storage.Length) return false;
            }

            // This copy uses safely validated bounds
            Buffer.BlockCopy(fragment, 0, storage, destOffset, length);
            return true;
        }

        public async Task HandleClientAsync(TcpClient client)
        {
            using (var stream = client.GetStream())
            {
                byte[] headerBuf = new byte[HEADER_SIZE];
                while (client.Connected)
                {
                    int read = await stream.ReadAsync(headerBuf, 0, HEADER_SIZE);
                    if (read < HEADER_SIZE) break;

                    var header = ParseHeader(headerBuf);
                    if (header == null) break;

                    // Validate PayloadLength before allocating
                    if (header.PayloadLength < 0 || header.PayloadLength > 65536) break;

                    byte[] packet = new byte[HEADER_SIZE + header.PayloadLength];
                    Buffer.BlockCopy(headerBuf, 0, packet, 0, HEADER_SIZE);

                    int remaining = header.PayloadLength;
                    int pos = HEADER_SIZE;
                    while (remaining > 0)
                    {
                        int chunk = await stream.ReadAsync(packet, pos, remaining);
                        if (chunk == 0) break;
                        pos += chunk;
                        remaining -= chunk;
                    }

                    ProcessIncomingPacket(packet);
                }
            }
        }
    }
}
